# 4.1 — đăng nhập: 4624/4625/4634/4647 và Logon Type, trên log Security mẫu công khai (2-system-Security-dirty.evtx: một máy Windows 10 thật 2018–2019,
# Archive-ForwardedEvents-test.evtx: log chuyển tiếp của nhiều máy, tc/smb-doan-mk-4625.evtx: DeepBlueCLI — đoán mật khẩu SMB, tc/han-che-4625.evtx: EVTX-to-MITRE-Attack).
!evtx-rec mau/2-system-Security-dirty.evtx 2>/dev/null > /lab/ra/d.jsonl
@ps Get-Content /lab/ra/d.jsonl | ConvertFrom-Json | Where-Object id -eq 4624 | Group-Object { $_.data.LogonType } | Sort-Object Count -Descending | Select-Object Count,@{n='LogonType';e={$_.Name}} | Format-Table -AutoSize
@ps Get-Content /lab/ra/d.jsonl | ConvertFrom-Json | Where-Object { $_.id -eq 4624 -and $_.data.LogonType -eq 10 } | ForEach-Object { [pscustomobject]@{ Luc = $_.t.ToString('s'); User = $_.data.TargetUserName; IP = $_.data.IpAddress; May = $_.data.WorkstationName; LogonId = $_.data.TargetLogonId } } | Format-Table -AutoSize
@ps Get-Content /lab/ra/d.jsonl | ConvertFrom-Json | Where-Object { $_.data.TargetLogonId -eq '0x7ac7caf' -or $_.data.SubjectLogonId -eq '0x7ac7caf' } | Group-Object id | Select-Object Count,@{n='EventID';e={$_.Name}},@{n='DauTien';e={$_.Group[0].t.ToString('HH:mm:ss')}},@{n='CuoiCung';e={$_.Group[-1].t.ToString('HH:mm:ss')}} | Format-Table -AutoSize
@ps Get-Content /lab/ra/d.jsonl | ConvertFrom-Json | Where-Object { $_.data.SubjectLogonId -eq '0x7ac7caf' -and $_.id -in 4732,4798 } | ForEach-Object { '{0}  {1}  {2}  {3}' -f $_.t.ToString('HH:mm:ss'), $_.id, $_.data.TargetUserName, $_.data.MemberSid } | Select-Object -Unique
@ps Get-Content /lab/ra/d.jsonl | ConvertFrom-Json | Where-Object rec -in 10512,10513 | ForEach-Object { [pscustomobject]@{ Rec = $_.rec; User = $_.data.TargetUserName; Type = $_.data.LogonType; LogonId = $_.data.TargetLogonId; Linked = $_.data.TargetLinkedLogonId; Elevated = $_.data.ElevatedToken } } | Format-Table -AutoSize
@ps Get-Content /lab/ra/d.jsonl | ConvertFrom-Json | Where-Object id -in 4624,4634,4647 | Group-Object id | Select-Object Count,Name | Format-Table -AutoSize
!evtx-rec tc/smb-doan-mk-4625.evtx 2>/dev/null > /lab/ra/smb.jsonl
@ps $e = Get-Content /lab/ra/smb.jsonl | ConvertFrom-Json; $e.Count; $e[0].t.ToString('o'); $e[-1].t.ToString('o'); ($e | Group-Object { $_.data.IpAddress }).Name
@ps Get-Content /lab/ra/smb.jsonl | ConvertFrom-Json | Group-Object { '{0} {1} {2} {3}' -f $_.data.LogonType, $_.data.Status, $_.data.SubStatus, $_.data.TargetUserName } | Select-Object Count,@{n='Type Status SubStatus User';e={$_.Name}} | Format-Table -AutoSize
@ps Get-Content /lab/ra/smb.jsonl | ConvertFrom-Json | Group-Object { $_.t.ToString('HH:mm') } | Select-Object Count,@{n='Phut';e={$_.Name}} | Format-Table -AutoSize
@ps Get-Content /lab/ra/smb.jsonl | ConvertFrom-Json | Select-Object -First 4 | ForEach-Object { '{0}  May={1}  Proc={2}  Pkg={3}' -f $_.t.ToString('HH:mm:ss.fff'), $_.data.WorkstationName, $_.data.LogonProcessName.Trim(), $_.data.AuthenticationPackageName }
@ps evtx-rec mau/Archive-ForwardedEvents-test.evtx | ConvertFrom-Json | Where-Object id -eq 4625 | Group-Object { '{0} {1} {2}' -f $_.data.SubStatus, $_.data.WorkstationName, $_.data.TargetUserName } | Sort-Object Count -Descending | Select-Object -First 6 Count,@{n='SubStatus May User';e={$_.Name}} | Format-Table -AutoSize
@ps evtx-rec tc/han-che-4625.evtx | ConvertFrom-Json | Where-Object id -eq 4625 | ForEach-Object { [pscustomobject]@{ Luc = $_.t.ToString('s'); User = $_.data.TargetUserName; Type = $_.data.LogonType; Status = $_.data.Status; Sub = $_.data.SubStatus; IP = $_.data.IpAddress } } | Format-Table -AutoSize
